INSERT INTO pages (slug, title, status, content, seo)
VALUES
('privacy-policy', $page$Privacy Policy$page$, 'published', $page${"meta":"<strong>Last updated</strong><br>\r\n      August 10, 2026<br><br>\n      Kasumigaseki Capital MENA<br>\r\n      Dubai, United Arab Emirates","body":"<h2>Overview</h2>\n        <p>Kasumigaseki MENA respects the privacy of website visitors, business contacts, candidates, prospective investors, suppliers, restaurant guests, and other individuals who interact with this website or contact us through the details provided on it.</p>\n        <p>This policy explains the categories of information we may collect, how we use it, when it may be shared, and the choices available to users.</p>\n\n        <h2>Who we are</h2>\n        <p>Kasumigaseki MENA is the regional subsidiary of Kasumigaseki Capital Co., Ltd., headquartered in Tokyo. For privacy enquiries relating to this website, contact <a href=\"mailto:info.dubai@kasumigaseki.co.jp\">info.dubai@kasumigaseki.co.jp</a>.</p>\n\n        <h2>Information we collect</h2>\n        <p>We may collect information that you voluntarily provide, including your name, email address, telephone number, company, role, enquiry details, employment information, preferred location, restaurant or meeting request details, and any message or attachment you submit by email or through website forms.</p>\n        <p>We may also collect technical and usage information, such as IP address, browser type, device information, pages visited, referring URLs, approximate location inferred from technical data, consent choices, and date and time of access.</p>\n\n        <h2>How we use information</h2>\n        <p>We may use information to respond to enquiries, manage business relationships, consider investment or partnership opportunities, handle recruitment and career communications, coordinate visits or meetings, provide requested information, maintain website security, understand website usage, improve content, and meet legal, regulatory, compliance, accounting, or governance requirements.</p>\n\n        <h2>Legal bases and consent</h2>\n        <p>Where applicable law requires a legal basis, we process personal information based on consent, legitimate business interests, steps taken at your request before entering into an arrangement, performance of a contract, compliance with legal obligations, or protection of legal rights and security.</p>\n        <p>For non-essential cookies or usage measurement, we rely on the cookie and usage consent choices presented on this website where required.</p>\n\n        <h2>Sharing information</h2>\n        <p>We may share information with Kasumigaseki Capital group companies, affiliates, professional advisers, service providers, hosting providers, IT support, analytics or media providers, recruitment support providers, and relevant authorities where needed for the purposes described in this policy.</p>\n        <p>We do not sell personal information.</p>\n\n        <h2>International transfers</h2>\n        <p>Because Kasumigaseki MENA operates as part of an international group, information may be accessed or processed in the United Arab Emirates, Japan, the United States, Malaysia, or other jurisdictions where group companies, service providers, or partners operate. We take reasonable steps to protect information when it is transferred or accessed internationally.</p>\n\n        <h2>Retention</h2>\n        <p>We retain information only for as long as reasonably necessary for the purpose for which it was collected, including responding to enquiries, managing relationships, maintaining records, resolving disputes, complying with legal obligations, and supporting internal governance. Retention periods may vary depending on the type of information and applicable requirements.</p>\n\n        <h2>Cookies and usage data</h2>\n        <p>This website may use cookies, local storage, server logs, embedded media, maps, fonts, and similar technologies. Details are available in our <a href=\"/cookie-policy/\">Cookie Policy</a>. You can manage consent through the cookie banner or the cookie settings control on the Cookie Policy page.</p>\n\n        <h2>Your rights and choices</h2>\n        <p>Depending on your jurisdiction, you may have rights to request access, correction, deletion, restriction, objection, portability, withdrawal of consent, or information about how your personal data is used. We may need to verify your identity before responding to a request.</p>\n        <p>Requests may be sent to <a href=\"mailto:info.dubai@kasumigaseki.co.jp\">info.dubai@kasumigaseki.co.jp</a>. We will respond as reasonably practicable and in accordance with applicable law.</p>\n\n        <h2>Security</h2>\n        <p>We use reasonable administrative, technical, and organizational measures to protect information. No online transmission, website, email system, or storage method can be guaranteed as completely secure.</p>\n\n        <h2>Children</h2>\n        <p>This website is not directed to children and is intended for business, investor, media, candidate, and general corporate audiences.</p>\n\n        <h2>Updates</h2>\n        <p>We may update this policy as our website, services, or legal requirements change. The latest version will be posted on this page.</p>"}$page$::jsonb, $page${"title":"Privacy Policy | Kasumigaseki MENA","description":"Privacy policy for Kasumigaseki MENA website visitors and enquiry submissions."}$page$::jsonb),
('terms-and-conditions', $page$Terms & Conditions$page$, 'published', $page${"meta":"<strong>Last updated</strong><br>\r\n      August 10, 2026<br><br>\n      Kasumigaseki Capital MENA<br>\r\n      Dubai, United Arab Emirates","body":"<h2>Acceptance of these terms</h2>\n        <p>These Terms &amp; Conditions govern access to and use of the Kasumigaseki MENA website. By browsing this website, submitting an enquiry, using linked resources, or continuing after a cookie or usage notice is displayed, you agree to use the website lawfully and in accordance with these terms.</p>\n        <p>If you do not agree with these terms, please stop using this website.</p>\n\n        <h2>About this website</h2>\n        <p>This website provides general corporate information about Kasumigaseki MENA, the regional subsidiary of Kasumigaseki Capital Co., Ltd., headquartered in Tokyo. It may include information about business activities, projects, locations, investment themes, group entities, news, and external resources.</p>\n        <p>Website content is provided for general information only and may be changed, suspended, corrected, or removed at any time without prior notice.</p>\n\n        <h2>No offer, advice, or recommendation</h2>\n        <p>Nothing on this website is intended to constitute an offer, solicitation, invitation, recommendation, commitment, or advice relating to any securities, fund, investment product, financial instrument, property transaction, employment opportunity, restaurant booking, or other service.</p>\n        <p>Users should make their own independent assessments and obtain professional advice before making decisions based on information available through this website.</p>\n\n        <h2>Forward-looking information</h2>\n        <p>Any statements about future plans, project timelines, market conditions, expected performance, strategy, or business outlook are based on information available at the time of publication and are subject to risks, assumptions, and uncertainties. Actual outcomes may differ materially.</p>\n\n        <h2>Permitted use</h2>\n        <p>You may access and view this website for legitimate personal, informational, or business reference purposes. You must not misuse the website, interfere with its operation, attempt unauthorized access, introduce malicious code, scrape content at scale, impersonate another person, or use the website in a way that may damage Kasumigaseki MENA, its affiliates, partners, or users.</p>\n\n        <h2>Intellectual property and asset usage</h2>\n        <p>All names, logos, marks, photographs, videos, graphics, text, page layouts, and other materials on this website are owned by or licensed to Kasumigaseki MENA, Kasumigaseki Capital group companies, or relevant third-party owners, unless otherwise stated.</p>\n        <p>You may not reproduce, modify, publish, distribute, frame, extract, use in advertising, use in marketing, or commercially exploit website materials without prior written permission. Requests relating to Kasumigaseki MENA materials may be sent to <a href=\"mailto:info.dubai@kasumigaseki.co.jp\">info.dubai@kasumigaseki.co.jp</a>.</p>\n\n        <h2>Third-party websites and services</h2>\n        <p>This website may contain links to group company websites, map services, media sources, social platforms, hospitality brands, logistics businesses, healthcare entities, and other third-party websites. These links are provided for convenience only.</p>\n        <p>Kasumigaseki MENA does not control and is not responsible for the availability, accuracy, security, content, cookies, privacy practices, or terms of third-party websites.</p>\n\n        <h2>Website availability and security</h2>\n        <p>Kasumigaseki MENA aims to keep the website accessible and useful, but does not guarantee uninterrupted operation, error-free performance, compatibility with every browser or device, or the absence of harmful components. Users are responsible for maintaining appropriate browser, device, and security settings.</p>\n\n        <h2>Limitation of liability</h2>\n        <p>To the fullest extent permitted by applicable law, Kasumigaseki MENA and its affiliates are not liable for any direct, indirect, incidental, consequential, special, punitive, or other loss arising from use of this website, reliance on website content, linked third-party services, technical interruption, data transmission, or inability to access the website.</p>\n\n        <h2>Changes to these terms</h2>\n        <p>Kasumigaseki MENA may update these terms from time to time. The latest version will be posted on this page and will apply from the date shown above.</p>\n\n        <h2>Contact</h2>\n        <p>Questions about these terms may be sent to <a href=\"mailto:info.dubai@kasumigaseki.co.jp\">info.dubai@kasumigaseki.co.jp</a>.</p>"}$page$::jsonb, $page${"title":"Terms & Conditions | Kasumigaseki MENA","description":"Terms and conditions for using the Kasumigaseki MENA website."}$page$::jsonb),
('cookie-policy', $page$Cookie Policy$page$, 'published', $page${"meta":"<strong>Last updated</strong><br>\r\n      August 10, 2026<br><br>\n      Kasumigaseki Capital MENA<br>\r\n      Dubai, United Arab Emirates","body":"<h2>What cookies and similar technologies are</h2>\n        <p>Cookies are small text files placed on a browser or device by a website or related service. Similar technologies include local storage, pixels, tags, scripts, embedded media, and server logs. They help websites operate, remember preferences, measure usage, maintain security, and support third-party features.</p>\n\n        <h2>Cookie and usage consent</h2>\n        <p>When you first visit this website, a consent notice may ask whether you agree to optional cookies and usage measurement. Essential technologies are used where needed for the website to function. Optional usage and media technologies are used only according to the choice you make where consent is required.</p>\n        <p><button class=\"legal-consent-button\" type=\"button\" data-cookie-settings>Open Cookie Settings</button></p>\n\n        <h2>Categories we use</h2>\n        <ul>\n          <li><strong>Essential:</strong> required for core website operation, security, consent storage, page navigation, and basic functionality.</li>\n          <li><strong>Usage analytics:</strong> helps us understand how visitors use the website so we can improve content, performance, and user experience. Usage data is intended to be used in aggregated or statistical form.</li>\n          <li><strong>Functional media and external services:</strong> supports embedded videos, maps, social links, font delivery, and other third-party features. These providers may process technical information under their own policies.</li>\n        </ul>\n\n        <h2>Third-party services</h2>\n        <p>This website may link to or load resources from third-party providers, including map platforms, video or media platforms, social media, font providers, analytics tools, and group company websites. These providers may set cookies or collect technical information when you interact with their services.</p>\n\n        <h2>How long choices are stored</h2>\n        <p>Your cookie and usage consent preference is stored in your browser using local storage so the website can remember your selection. If you clear browser storage or use another device, the consent notice may appear again.</p>\n\n        <h2>Managing cookies in your browser</h2>\n        <p>Most browsers allow you to block, delete, or manage cookies through settings. Blocking certain cookies may affect website performance or availability of media, maps, or other features.</p>\n\n        <h2>Updates</h2>\n        <p>This policy may be updated as website features, third-party services, or legal requirements change. The latest version will be posted on this page.</p>"}$page$::jsonb, $page${"title":"Cookie Policy | Kasumigaseki MENA","description":"Cookie policy for the Kasumigaseki MENA website."}$page$::jsonb),
('legal-notice', $page$Legal Notice$page$, 'published', $page${"meta":"<strong>Last updated</strong><br>\r\n      August 10, 2026<br><br>\n      Kasumigaseki Capital MENA<br>\r\n      Dubai, United Arab Emirates","body":"<h2>Website operator</h2>\n        <p>This website is operated for Kasumigaseki Capital MENA in Dubai, United Arab Emirates. General enquiries may be sent to <a href=\"mailto:info.dubai@kasumigaseki.co.jp\">info.dubai@kasumigaseki.co.jp</a>.</p>\n\n        <h2>Corporate positioning</h2>\n        <p>Kasumigaseki MENA is the regional subsidiary of Kasumigaseki Capital Co., Ltd., headquartered in Tokyo. The website presents regional business activities, investment themes, locations, and operating capabilities for general information.</p>\n\n        <h2>Site policy and technical use</h2>\n        <p>This website is intended for modern browsers and devices with standard web technologies enabled, including JavaScript where needed for navigation, media, forms, cookie consent, and interactive features. Some features may not operate correctly on outdated browsers, restricted networks, disabled scripts, or unsupported devices.</p>\n\n        <h2>Accuracy, updates, and availability</h2>\n        <p>Kasumigaseki MENA aims to provide accurate and useful information, but does not guarantee completeness, timeliness, accuracy, availability, security, or suitability for any particular purpose. Content, URLs, features, media, and linked materials may be changed or removed without notice.</p>\n\n        <h2>No professional advice or offer</h2>\n        <p>Website content is not investment, financial, legal, tax, accounting, technical, real estate, employment, or other professional advice. It is also not an offer, solicitation, recommendation, or commitment relating to any securities, property, investment product, fund, service, employment position, or transaction.</p>\n\n        <h2>Forward-looking information</h2>\n        <p>Statements about future plans, markets, projects, strategy, outlook, development timelines, business expansion, or expected performance are subject to assumptions, risks, and uncertainties. Actual outcomes may differ materially.</p>\n\n        <h2>Copyright, trademarks, and asset usage</h2>\n        <p>Kasumigaseki names, logos, marks, website content, photographs, videos, graphics, design elements, and other assets are protected by applicable intellectual property laws. Unauthorized copying, editing, distribution, publication, commercial use, advertising use, or brand association is prohibited.</p>\n        <p>Some images, maps, videos, marks, or linked materials may belong to third parties. Permission from Kasumigaseki MENA does not grant rights in third-party assets. Requests relating to website materials may be sent to <a href=\"mailto:info.dubai@kasumigaseki.co.jp\">info.dubai@kasumigaseki.co.jp</a>.</p>\n\n        <h2>External links</h2>\n        <p>Links to third-party websites are provided for convenience and context. Kasumigaseki MENA does not control third-party websites and is not responsible for their content, security, policies, availability, or use of cookies and tracking technologies.</p>\n\n        <h2>Compliance stance</h2>\n        <p>Kasumigaseki MENA is committed to lawful, ethical, and responsible business conduct. We do not knowingly support unlawful activity, corruption, fraud, money laundering, terrorist financing, sanctions evasion, or relationships with anti-social or criminal organizations.</p>\n\n        <h2>Contact</h2>\n        <p>For website, legal, privacy, or asset usage enquiries, contact <a href=\"mailto:info.dubai@kasumigaseki.co.jp\">info.dubai@kasumigaseki.co.jp</a>.</p>"}$page$::jsonb, $page${"title":"Legal Notice | Kasumigaseki MENA","description":"Legal notice and corporate information for the Kasumigaseki MENA website."}$page$::jsonb)
